package com.guocheng.mediapocket;
import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
final class FusionArtwork {
 static final ExecutorService IO=new ThreadPoolExecutor(2,2,0,TimeUnit.SECONDS,new ArrayBlockingQueue<Runnable>(12));static final Set<String> pending=Collections.synchronizedSet(new HashSet<String>());
 static String key(JSONObject m){return "fusion.match.v1:"+MediaMatchRules.key(m.optString("name",m.optString("vod_name")))+":"+m.optString("releaseInfo",m.optString("vod_year"));}
 static JSONObject cached(Context c,JSONObject m){try{return new JSONObject(c.getSharedPreferences("data",0).getString(key(m),""));}catch(Exception e){return null;}}
 static JSONArray search(String query)throws Exception{JSONArray out=new JSONArray();for(String type:new String[]{"movie","series"}){try{JSONArray items=CinemaCatalogClient.json("https://v3-cinemeta.strem.io/catalog/"+type+"/top/search="+Net.esc(MediaMatchRules.clean(query))+".json").optJSONArray("metas");for(int i=0;items!=null&&i<Math.min(12,items.length());i++){JSONObject m=items.optJSONObject(i);if(m!=null&&!MediaMatchRules.imdb(m.optString("id")).isEmpty()){m.put("type",type);out.put(m);}}}catch(Exception e){if(type.equals("series")&&out.length()==0)throw e;}}return out;}
 static void save(Context c,JSONObject input,JSONObject match){c.getSharedPreferences("data",0).edit().putString(key(input),match.toString()).apply();}
 static void fill(JSONObject m,JSONObject match)throws Exception{if(match==null)return;m.put("poster",match.optString("poster"));m.put("fusion.imdb",match.optString("id")).put("fusion.mediaType",match.optString("type","movie"));if(m.optString("background").isEmpty())m.put("background",match.optString("background",match.optString("poster")));}
 interface Result{void done(JSONObject match);}
 static void resolve(Context c,JSONObject m,Result result){JSONObject cached=cached(c,m);if(cached!=null){result.done(cached);return;}String key=key(m);if(c.getSharedPreferences("data",0).getLong(key+".miss",0)>System.currentTimeMillis()-86400000L)return;if(pending.size()>=12||!pending.add(key))return;try{IO.execute(()->{try{JSONArray items=search(m.optString("name",m.optString("vod_name")));JSONObject match=null;int count=0;for(int i=0;i<items.length();i++){JSONObject candidate=items.optJSONObject(i);if(MediaMatchRules.key(candidate.optString("name")).equals(MediaMatchRules.key(m.optString("name",m.optString("vod_name"))))){String year=m.optString("releaseInfo",m.optString("vod_year"));if(!year.isEmpty()&&!candidate.optString("releaseInfo").contains(year))continue;count++;match=candidate;}}if(count==1){save(c,m,match);result.done(match);}else c.getSharedPreferences("data",0).edit().putLong(key+".miss",System.currentTimeMillis()).apply();}catch(Exception ignored){}finally{pending.remove(key);}});}catch(RejectedExecutionException e){pending.remove(key);}}
}
